import Foundation

struct VocabularyWord: Identifiable, Hashable, Codable {
    let text: String
    let partOfSpeech: String
    let meaning: String
    let examples: [String]
    var example: String { examples.first ?? "" }

    init(text: String, partOfSpeech: String, meaning: String, example: String) {
        self.init(text: text, partOfSpeech: partOfSpeech, meaning: meaning, examples: [example])
    }

    init(text: String, partOfSpeech: String, meaning: String, examples: [String]) {
        self.text = text
        self.partOfSpeech = partOfSpeech
        self.meaning = meaning
        self.examples = examples
    }

    var id: String { text }
}

struct VocabularyTopic: Identifiable {
    let id: String
    let name: String
